head.b:skin:
:root{--brand:#0f766e;--brand2:#115e59;--text:#172033;--muted:#64748b;--bg:#f8fafc;--line:#e2e8f0;--white:#fff;--max:1180px;--r:18px;--shadow:0 12px 32px rgba(15,23,42,.08)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.65 Inter,system-ui,-apple-system,"Segoe UI",Arial,sans-serif}a{color:inherit;text-decoration:none}img{max-width:100%;height:auto}.container{width:min(calc(100% - 32px),var(--max));margin:auto}
.header{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.95);border-bottom:1px solid var(--line);backdrop-filter:blur(12px)}.nav{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:22px}.brand{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:900}.mark{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;background:linear-gradient(135deg,var(--brand),#14b8a6);color:#fff}.links{display:flex;align-items:center;gap:22px;font-size:14px;font-weight:700}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:0 20px;border-radius:12px;border:1px solid transparent;font-weight:800}.primary{background:var(--brand);color:#fff}.primary:hover{background:var(--brand2)}.light{background:#fff;border-color:var(--line)}
.hero{padding:84px 0 72px;background:radial-gradient(circle at 82% 18%,rgba(20,184,166,.16),transparent 30%),linear-gradient(180deg,#fff,#f0fdfa);border-bottom:1px solid var(--line)}.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:52px;align-items:center}.tag{display:inline-flex;padding:7px 12px;border-radius:99px;background:#ccfbf1;color:#115e59;font-size:13px;font-weight:900}.hero h1{font-size:clamp(42px,6vw,70px);line-height:1.05;letter-spacing:-.045em;margin:18px 0}.hero p{max-width:680px;color:var(--muted);font-size:19px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}.hero-card{padding:28px;background:#fff;border:1px solid var(--line);border-radius:26px;box-shadow:var(--shadow)}.stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.stat{padding:18px;background:#f8fafc;border:1px solid var(--line);border-radius:15px}.stat strong{display:block;color:var(--brand);font-size:25px}.stat span{font-size:13px;color:var(--muted)}
.section{padding:72px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:26px}.section-head h2{margin:0;font-size:34px;letter-spacing:-.03em}.section-head p{margin:5px 0 0;color:var(--muted)}.benefits{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.benefit{padding:23px;background:#fff;border:1px solid var(--line);border-radius:var(--r)}.benefit b{display:block;margin-bottom:7px;font-size:18px}.benefit p{margin:0;color:var(--muted);font-size:14px}
.toolbar{display:grid;grid-template-columns:minmax(250px,1.6fr) repeat(3,minmax(145px,.7fr));gap:10px}.search{display:flex;align-items:center;padding:0 12px;background:#fff;border:1px solid var(--line);border-radius:12px}.search input{width:100%;padding:13px 8px;border:0;outline:0;background:transparent;font:inherit}.filter{min-height:48px;padding:0 12px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--text);font:inherit}.summary{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:12px 0 22px;color:var(--muted);font-size:14px}.clear{border:0;background:none;color:var(--brand);font:inherit;font-weight:900;cursor:pointer}.jobs{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.job{display:flex;flex-direction:column;min-height:245px;padding:23px;background:#fff;border:1px solid var(--line);border-radius:var(--r);transition:.2s}.job:hover{transform:translateY(-3px);box-shadow:var(--shadow);border-color:#99f6e4}.chips{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:15px}.chip{padding:5px 9px;border-radius:99px;background:#f1f5f9;color:#475569;font-size:12px;font-weight:800}.job h3{margin:0 0 10px;font-size:21px;line-height:1.35}.job p{margin:0 0 18px;color:var(--muted);font-size:14px}.job-more{margin-top:auto;color:var(--brand);font-weight:900}.empty{display:none;padding:34px;margin-top:20px;text-align:center;color:var(--muted);background:#fff;border:1px dashed #cbd5e1;border-radius:var(--r)}
.cta{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:42px;background:linear-gradient(135deg,var(--brand2),var(--brand));color:#fff;border-radius:26px}.cta h2{margin:0 0 7px;font-size:31px}.cta p{margin:0;color:#ccfbf1}.cta .btn{background:#fff;color:var(--brand2)}
.content{width:min(calc(100% - 32px),880px);margin:48px auto;padding:36px;background:#fff;border:1px solid var(--line);border-radius:24px}.content h1{margin:0 0 12px;font-size:38px;line-height:1.15}.post-body h2,.post-body h3{margin-top:28px}.apply{margin-top:32px;padding:23px;background:#f0fdfa;border:1px solid #99f6e4;border-radius:17px}
.footer{margin-top:70px;padding:48px 0 26px;background:#0f172a;color:#cbd5e1}.foot{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:28px}.footer h4{color:#fff}.copy{margin-top:30px;padding-top:18px;border-top:1px solid #334155;color:#94a3b8;font-size:13px}.mobile{display:none}
@media(max-width:900px){.hero-grid,.foot{grid-template-columns:1fr}.benefits,.jobs{grid-template-columns:repeat(2,1fr)}.toolbar{grid-template-columns:1fr 1fr}.links{display:none}.mobile{display:inline-flex}}
@media(max-width:620px){.hero{padding:56px 0}.section{padding:54px 0}.benefits,.jobs,.toolbar{grid-template-columns:1fr}.summary,.cta{align-items:flex-start;flex-direction:column}.cta{padding:27px}.content{padding:23px}.hero h1{font-size:43px}}

body.script:
//
(function(){
  var q=document.getElementById('jobSearch'),d=document.getElementById('departmentFilter'),l=document.getElementById('locationFilter'),t=document.getElementById('typeFilter'),clear=document.getElementById('clearFilters'),count=document.getElementById('jobCount'),empty=document.getElementById('jobsEmpty'),jobs=[].slice.call(document.querySelectorAll('.job'));
  if(!q||!jobs.length)return;
  var P={d:'PB:',l:'ĐĐ:',t:'HT:'};
  function norm(v){return(v||'').toLocaleLowerCase('vi').trim()}
  function add(select,values){Object.keys(values).sort(function(a,b){return a.localeCompare(b,'vi')}).forEach(function(v){var o=document.createElement('option');o.value=v;o.textContent=v;select.appendChild(o)})}
  jobs.forEach(function(job){job.querySelectorAll('.chip').forEach(function(c){c.setAttribute('data-raw',(c.textContent||'').trim())})});
  function group(prefix){var out={};jobs.forEach(function(job){job.querySelectorAll('.chip').forEach(function(c){var raw=c.getAttribute('data-raw')||'';if(raw.indexOf(prefix)===0){var v=raw.slice(prefix.length).trim();if(v){out[v]=1;c.textContent=v}}})});return out}
  add(d,group(P.d));add(l,group(P.l));add(t,group(P.t));
  function has(job,prefix,value){if(!value)return true;return[].slice.call(job.querySelectorAll('.chip')).some(function(c){return norm(c.getAttribute('data-raw'))===norm(prefix+value)})}
  function run(){var text=norm(q.value),visible=0;jobs.forEach(function(job){var ok=(!text||norm(job.textContent).indexOf(text)>-1)&&has(job,P.d,d.value)&&has(job,P.l,l.value)&&has(job,P.t,t.value);job.style.display=ok?'flex':'none';if(ok)visible++});count.textContent=visible+' vị trí phù hợp';empty.style.display=visible?'none':'block'}
  q.addEventListener('input',run);[d,l,t].forEach(function(x){x.addEventListener('change',run)});clear.addEventListener('click',function(){q.value='';d.value='';l.value='';t.value='';run();q.focus()});run();
})();
//
